    gen_random_uuid(), v_lesson_id, 1, 'Failing Fast vs. Planning Carefully',
    '{"lesson_name": "Failing Fast vs. Planning Carefully", "lesson_description": "3SL1 [3SL1c] (93%) PRIMARY | 3SL4 (91%) PRIMARY | 3-5L1 (89%) SECONDARY", "training_module_id": "8addaf36-3881-49d8-ab34-444c399bf432", "grade": 3, "section": null, "difficulty_level": "HARD", "lesson_type": "Silly Topic Debate", "contents": [{"content_key": "topic", "content_value": "Failing fast and trying again is better than planning carefully before you start."}, {"content_key": "user_side", "content_value": "Planning Carefully"}, {"content_key": "ai_side", "content_value": "Failing Fast"}, {"content_key": "content", "content_value": "Failing fast gives you real information that no amount of planning can substitute for, because reality always surprises the plan.\nCompelling. What does careful planning prevent that rapid trial-and-error can never recover from once it goes wrong?\nFinal thought."}, {"content_key": "example_topic", "content_value": "Ice Cream is better than Pizza"}, {"content_key": "example_user_side", "content_value": "Ice cream is cold and sweet, and it makes people happy on hot days!"}, {"content_key": "example_ai_side", "content_value": "Pizza has cheese and toppings and can be eaten anytime, unlike ice cream."}]}',
    'published', true, NOW()
  );

