    (gen_random_uuid(), v_lesson_id, 'topic', 'Asking fewer, better questions is more valuable than asking many questions.', NOW(), NOW())
,    (gen_random_uuid(), v_lesson_id, 'user_side', 'Many Questions', NOW(), NOW())
,    (gen_random_uuid(), v_lesson_id, 'ai_side', 'Fewer Better Questions', NOW(), NOW())
,    (gen_random_uuid(), v_lesson_id, 'content', 'A precise question shows you have already done real thinking, and it gets you to a useful answer faster than a flood of questions can.
